import React from 'react';
import ReactDOM from 'react-dom';
import { TreeSelect } from '@alifd/next';
import '@alifd/next/dist/next.css';

const treeData = [
  {
    label: 'Component',
    value: '1',
    key: '1',
    children: [
      {
        label: 'Form',
        value: '2',
        key: '2',
        children: [
          {
            label: 'Input',
            value: '4',
            key: '4',
            disableCheckbox: true // the checkbox is disabled
          },
          {
            label: 'Select',
            value: '5',
            key: '5',
            disabled: true       // node is disabled
          }
        ]
      }
    ]
  }
];

function App() {
  return (
    <div style={{ padding: 20 }}>
      <TreeSelect
        dataSource={treeData}
        treeCheckable
        multiple
        treeDefaultExpandAll
        style={{ width: 300 }}
        defaultValue={['4']} // default select the disabled‐checkbox node
        placeholder="Please select"
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
